function validate([prices, queries]) {
  const n = prices.length;
  if (n < 1 || n > 100000) return 'prices needs 1 to 10^5 values.';
  if (prices.some(p => p < 1 || p > 1000000000)) return 'Each price is between 1 and 10^9.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (query.length !== 2) return 'Each query is [k, m].';
    if (query[0] < 1 || query[0] > 1000000000) return 'Each k is between 1 and 10^9.';
    if (query[1] < 1 || query[1] > n) return 'Each m is between 1 and prices.length.';
  }
  return null;
}

