function minimumRelativeLosses(prices, queries) {
  prices.sort((a, b) => a - b);
  const n = prices.length;
  const prefix = [0];
  for (const price of prices) {
    prefix.push(prefix[prefix.length - 1] + price);
  }
  const answer = [];
  for (const [k, m] of queries) {
    let low = 0;
    let high = m;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (prices[mid] + prices[n - m + mid] < 2 * k) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    const left = low;
    const right = m - left;
    const leftLoss = prefix[left];
    const rightLoss = 2 * k * right - (prefix[n] - prefix[n - right]);
    answer.push(leftLoss + rightLoss);
  }
  return answer;
}

