function minimumRelativeLosses(prices, queries) {
  // Each chocolate adds its own amount to b - a, so take the m smallest amounts.
  return queries.map(([k, m]) => {
    const losses = prices.map(price => price <= k ? price : k - (price - k));
    losses.sort((a, b) => a - b);
    let total = 0;
    for (let i = 0; i < m; i++) total += losses[i];
    return total;
  });
}

