function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const q = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 5);
  const top = large ? (rand() < 0.6 ? 1000000000 : 5000) : (rand() < 0.5 ? 6 : 30);
  const prices = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const queries = Array.from({ length: q }, () => {
    // k is often an existing price (ties with k) or close to one, sometimes anywhere.
    const r = rand();
    const base = prices[Math.floor(rand() * n)];
    const k = r < 0.4 ? base : r < 0.7 ? Math.max(1, Math.min(1000000000, base + Math.floor(rand() * 7) - 3)) : 1 + Math.floor(rand() * (top + 5));
    return [k, 1 + Math.floor(rand() * n)];
  });
  return [prices, queries];
}
